import numpy as np
from scipy.optimize import curve_fit
raw=open('graphene.dat').read().splitlines()
a=np.array([[float(v.replace(',','.')) for v in l.split()] for l in raw if l.strip()])
x=a[:,0]; y=a[:,1]
order=np.argsort(x); x=x[order]; y=y[order]

def lor(x,x0,gamma,amp,off,slope=0):
    return off+slope*(x-x0)+amp*gamma**2/((x-x0)**2+gamma**2)
def gau(x,x0,gamma,amp,off,slope=0):
    return off+slope*(x-x0)+amp*np.exp(-0.5*((x-x0)/gamma)**2)
def pvoigt(x,x0,gamma,amp,off,eta,slope=0):
    l=gamma**2/((x-x0)**2+gamma**2)
    g=np.exp(-0.5*((x-x0)/gamma)**2)
    return off+slope*(x-x0)+amp*(eta*l+(1-eta)*g)

def fit(c, half, model, p0):
    m=(x>c-half)&(x<c+half)
    xx=x[m]; yy=y[m]
    if model is lor:
        popt,pcov=curve_fit(model,xx,yy,p0=p0,maxfev=100000)
    elif model is gau:
        popt,pcov=curve_fit(model,xx,yy,p0=p0,maxfev=100000)
    else:
        popt,pcov=curve_fit(model,xx,yy,p0=p0,maxfev=100000,bounds=([-np.inf,-np.inf,-np.inf,-np.inf,0,-np.inf],[np.inf,np.inf,np.inf,np.inf,1,np.inf]))
    yfit=model(xx,*popt)
    rms=np.sqrt(np.mean((yy-yfit)**2))
    return popt,rms,m.sum()
for c in [3745.05,6329.37]:
 print('\n===== center',c,'=====')
 for half in [100,150,200,300,500]:
  if c==6329.37 and half>400: continue
  for model,p0 in [(lor,[c,30,10000,1500,0]),(gau,[c,30,10000,1500,0]),(pvoigt,[c,30,10000,1500,0.5,0])]:
   try:
    popt,rms,n=fit(c,half,model,p0)
    print(f"half={half:4d} {model.__name__:7s} n={n:3d} rms={rms:8.1f} x0={popt[0]:9.3f} gamma={popt[1]:8.3f} amp={popt[2]:9.1f} off={popt[3]:9.1f} slope={popt[-1]:8.3f}"+(f" eta={popt[4]:.3f}" if model is pvoigt else ""))
   except Exception as e: print('err',half,model.__name__,e)
